import { transform } from "./utils.js";
export default {
    tag: "f-choose",
    jsImport: "lume_cms/components/f-choose.js",
    async applyChanges(data, changes, field, document, cmsContent) {
        const value = changes[field.name];
        if (!value) {
            delete data[field.name];
            return;
        }
        const type = value.type;
        const chooseField = field.fields?.find((f) => f.name === type);
        if (!chooseField) {
            throw new Error(`No field found for type '${type}'`);
        }
        const newValue = { type };
        for (const f of chooseField?.fields || []) {
            await f.applyChanges(newValue, changes[field.name] || {}, f, document, cmsContent);
        }
        data[field.name] = transform(field, newValue);
    },
};
